import {pfCartPage,bindCart,updateCartHeader} from './pf-cart.mjs';
import {checkoutPage,orderPage,bindCheckout} from './checkout.mjs';
import {pfListing,pfDesign,pfComingSoon,bindPF} from './pf-studio.mjs';
import {isShopProduct,isQuoteOnlyProduct,isComingSoonProduct,shopProducts,pricedVariants} from './pf-visibility.mjs';
import {productGroups,groupSections,productGroupURL} from './product-groups.mjs';
import { specialPage, bindSpecial } from './special.mjs';
import { brandPreview, brandsPage } from './brands.mjs';
import {filterProducts,totalQuantity,validateLine,quoteLine} from './rules.mjs';
import {saveFile,loadFile,deleteFile} from './storage.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'Få tilbud':`${new Intl.NumberFormat('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)} kr.`;
let pfCatalog,pfPrices,catalog,cart=[],contact={},draft,activeProduct,previewURL;
const pfProductRequests=new Map();
try{const saved=JSON.parse(localStorage.getItem('merch-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(l=>l&&typeof l.productId==='string'&&typeof l.id==='string');}catch{}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){try{localStorage.setItem('merch-cart-v1',JSON.stringify(cart));updateCartHeader();return true;}catch{notify('Browseren kunne ikke gemme kurven. Frigør lagerplads og prøv igen.');return false;}}
function nav(url,{scrollTop=false,replace=false}={}){const next=new URL(url,location.href),keepPosition=!scrollTop&&next.pathname===location.pathname,scrollY=window.scrollY;history[replace?'replaceState':'pushState']({},'',next.pathname+next.search+next.hash);render();window.scrollTo(0,keepPosition?scrollY:0);$('#main').focus({preventScroll:true});}
function art(p){return `<div class="print-art ${p.art}" aria-label="Eksempel på ${esc(p.name)}"><span>Smerch<br>Design studio</span><strong>${p.art==='cards'?'Godt at\nmøde dig.':p.art==='flyer'?'Gør dit\nindtryk.':'Plads\ntil mere.'}</strong><span>Dit budskab. Dit format.</span></div>`;}
function picture(p,cls='',lazy=true){return p.art?art(p):`<img class="${cls}" src="${esc(p.colors[0].images[0])}" alt="${esc(p.name)} — demobillede" ${lazy?'loading="lazy"':''} width="700" height="700">`;}
function card(p){const tier=p.tiers.at(-1);return `<article class="product-card"><a class="product-image" href="/produkt/${p.id}"><span class="image-tag">${p.art?'TRYKSAGER':'DEMO'}</span>${picture(p)}<span class="round-link" aria-hidden="true">↗</span></a><div class="card-meta"><span>${esc(p.brand)}</span><span>${p.minimum} stk. min.</span></div><a href="/produkt/${p.id}" class="product-title">${esc(p.name)}</a><div class="card-bottom"><span>${tier?`Fra ${money(tier.unit)}`:'Få tilbud'}</span><div class="dots" aria-label="${esc(p.colors.map(c=>c.name).join(', '))}">${p.colors.map(c=>`<i style="background:${c.hex}"></i>`).join('')}</div></div><p class="price-note">${tier?`Demopris ved ${tier.min} stk. · ekskl. moms og tryk`:'Pris og specifikationer efter aftale'}</p></article>`;}
function visibleBrands(){if(!pfCatalog)return catalog.brands||[];const ids=new Set(shopProducts(pfCatalog,pfPrices).map(p=>p.brandId));return (catalog.brands||[]).filter(brand=>ids.has(brand.id));}
function liveProductImage(product){return pricedVariants(product,pfPrices).find(variant=>variant.images?.[0])?.images[0];}
function homeCategoryTiles(){
 const products=shopProducts(pfCatalog,pfPrices).filter(product=>pfPrices?.products?.[product.id]&&liveProductImage(product));
 const categories=[{id:'toj',name:'Tøj og tekstiler',modelCode:'38235',category:'Hættetrøjer'},{id:'tasker',name:'Tasker',modelCode:'120632',category:'Rygsække'},{id:'flasker',name:'Flasker og krus',modelCode:'100798',category:'Vandflasker'}];
 const tiles=categories.map(item=>{
  const matches=products.filter(product=>product.shopCategory===item.id);
  const product=matches.find(candidate=>candidate.modelCode===item.modelCode)||matches.find(candidate=>candidate.category===item.category)||matches[0];
  if(!product)return '';
  return `<a class="category-tile" href="/produkter?kategori=${item.id}"><div><img src="${esc(liveProductImage(product))}" alt="${esc(product.name)}" loading="lazy" decoding="async" width="700" height="700"></div><h3>${item.name}<span>↗</span></h3></a>`;
 }).join('');
 return tiles+`<a class="category-tile" href="/produkter?kategori=tryksager"><div>${art(catalog.products[6])}</div><h3>Tryksager<span>↗</span></h3></a>`;
}
function homeFeaturedProducts(){
 return shopProducts(pfCatalog,pfPrices).filter(product=>pfPrices?.products?.[product.id]&&liveProductImage(product)&&['thule','stanley-1913','moleskine','hydro-flask'].includes(product.brandId)).filter((product,index,all)=>all.findIndex(candidate=>candidate.brandId===product.brandId)===index).map(product=>`<article class="product-card"><a class="product-image" href="/design/${product.id}"><img src="${esc(liveProductImage(product))}" alt="${esc(product.name)}" loading="lazy" decoding="async" width="700" height="700"></a><p class="card-meta">${esc(product.brand)}</p><a class="product-title" href="/design/${product.id}">${esc(product.name)}</a></article>`).join('');
}
function closeProductMenu(){const menu=$('#product-menu'),toggle=$('#product-menu-toggle');menu.hidden=true;toggle.setAttribute('aria-expanded','false');}
function openProductMenu(groupId){
 const products=shopProducts(pfCatalog,pfPrices),groups=productGroups.filter(group=>products.some(product=>product.shopCategory===group.id));
 if(!groups.length)return;
 const active=groups.find(group=>group.id===groupId)||groups[0],sections=groupSections(active,products);
 $('#product-menu').innerHTML=`<div class="wrap product-mega-layout"><div class="product-mega-groups"><p class="eyebrow">Produktgrupper</p>${groups.map(group=>`<button type="button" data-menu-group="${group.id}" class="${group.id===active.id?'active':''}" aria-pressed="${group.id===active.id}">${esc(group.name)} <span aria-hidden="true">→</span></button>`).join('')}<a href="/produkter">Se alle produkter ↗</a></div><div class="product-mega-content"><div class="product-mega-heading"><div><p class="eyebrow">Find det rigtige</p><h2>${esc(active.name)}</h2></div><a href="${productGroupURL(active.id)}">Se alle i gruppen ↗</a></div><div class="product-mega-sections">${sections.map(section=>`<section><h3>${esc(section.name)}</h3>${section.items.map(item=>`<a href="${productGroupURL(active.id,item.name)}">${esc(item.name)} <small>${item.count}</small></a>`).join('')}</section>`).join('')}</div></div></div>`;
 $('#product-menu').hidden=false;$('#product-menu-toggle').setAttribute('aria-expanded','true');
}
function home(){return `<section class="hero home-hero"><div class="hero-copy"><p class="eyebrow">Merchandise · design · identitet</p><h1>Merch, der<br>gør jeres brand<br><em>synligt.</em></h1><p>Udvalgte produkter, stærke brands og jeres identitet samlet i ét skarpt udtryk.</p><div class="hero-actions"><a class="button light" href="/produkter">Shop kollektionen <span>↗</span></a><a class="hero-link" href="/brands">Se alle brands <span>↗</span></a></div></div><div class="hero-image"><img src="/assets/hero.jpg" alt="Kasket, drikkeflaske, T-shirt og mulepose i et lyst produktunivers" fetchpriority="high" width="1536" height="1024"><div class="hero-stamp"><b>SMERCH</b><span>YOUR BRAND<br>IN MOTION</span></div><span class="hero-caption">01 · Udvalgte produkter</span></div></section><div class="value-strip home-value-strip"><span>01 · Udvalgte premiumbrands</span><span>02 · Pris mens I designer</span><span>03 · Korrektur før produktion</span></div>${brandPreview(visibleBrands())}<section class="wrap section home-categories"><div class="section-heading"><div><p class="eyebrow">Find jeres format</p><h2>Hvad skal bære<br>jeres brand?</h2></div><a href="/produkter" class="text-link">Se hele kollektionen ↗</a></div><div class="category-grid">${homeCategoryTiles()}</div></section><section class="wrap section home-featured"><div class="section-heading"><div><p class="eyebrow">Udvalgt til arbejde og hverdag</p><h2>Udvalgt lige nu.</h2></div><a href="/produkter" class="text-link">Udforsk kataloget ↗</a></div><div class="product-grid">${homeFeaturedProducts()}</div></section><section class="process home-process"><div class="wrap"><div class="process-heading"><div><p class="eyebrow">Fra idé til færdigt merch</p><h2>Et enkelt flow.<br>Et skarpere resultat.</h2></div><p>Vi gør vejen fra produktvalg til godkendt korrektur overskuelig, så I kan holde fokus på udtrykket.</p></div><div class="steps"><div><span>01</span><h3>Find jeres favoritter</h3><p>Vælg de produkter, der passer til menneskerne og anledningen.</p></div><div><span>02</span><h3>Tilføj jeres identitet</h3><p>Vælg farver, antal og tryk. Placér logoet direkte på produktet.</p></div><div><span>03</span><h3>Godkend udtrykket</h3><p>Se korrekturen, godkend detaljerne og send først derefter i produktion.</p></div></div></div></section><section class="home-manifesto"><div class="wrap"><p class="eyebrow">Smerch · København</p><h2>Jeres brand fortjener<br><em>mere end standard.</em></h2><p>Skab merchandise, som folk har lyst til at tage med sig.</p><a class="button dark" href="/produkter">Start jeres kollektion <span>↗</span></a></div></section>`;}
function select(name,label,values,current,blank='Alle'){return `<label>${label}<select name="${name}"><option value="">${blank}</option>${values.map(v=>{const val=typeof v==='string'?v:v.value;return `<option value="${esc(val)}" ${current===val?'selected':''}>${esc(typeof v==='string'?v:v.label)}</option>`}).join('')}</select></label>`;}
function listing(){if(pfCatalog&&!new URLSearchParams(location.search).has('demo')&&new URLSearchParams(location.search).get('kategori')!=='tryksager')return pfListing(pfCatalog,pfCatalog.brands||catalog.brands,pfPrices);
const params=new URLSearchParams(location.search),filtered=filterProducts(catalog.products,params),cat=catalog.categories.find(c=>c.id===params.get('kategori'));return `<section class="catalog-heading"><div class="wrap"><p class="eyebrow">MERCHANDISE MED OMTANKE FOR DIT BRAND</p><h1>${cat?cat.name:'Gode ting. Dit logo.'}</h1><p>${cat?.id==='tryksager'?'Fra papir til et personligt indtryk. Vælg format og saml dine ønsker.':'Find de produkter, der passer til jeres hverdag, mennesker og næste event.'}</p></div></section><div class="wrap special-catalog-link"><a class="text-link" href="/specialproduktion">Kan du ikke finde det, du søger? Specialproduktion ↗</a></div><div class="category-nav wrap"><a class="${!cat?'active':''}" href="/produkter">Alle produkter</a>${catalog.categories.map(c=>`<a class="${c.id===cat?.id?'active':''}" href="/produkter?kategori=${c.id}">${c.name}</a>`).join('')}</div><section class="wrap catalog-body"><details class="filter-panel" ${window.matchMedia('(min-width: 701px)').matches?'open':''}><summary>Filtrér produkter</summary><form id="filters">${select('kategori','Kategori',catalog.categories.map(c=>({value:c.id,label:c.name})),params.get('kategori'))}<label>Søg i kataloget<input name="q" value="${esc(params.get('q')||'')}" placeholder="Produkt eller varenummer"></label>${select('farve','Farve',[...new Set(catalog.products.flatMap(p=>p.colors.map(c=>c.name)))],params.get('farve'))}${select('brand','Brand / sortiment',[...new Set(catalog.products.map(p=>p.brand))],params.get('brand'))}${select('materiale','Materiale',[...new Set(catalog.products.map(p=>p.material))],params.get('materiale'))}${select('pris','Demopris pr. stk.',[{value:'50',label:'Op til 50 kr.'},{value:'100',label:'Op til 100 kr.'},{value:'200',label:'Op til 200 kr.'},{value:'tilbud',label:'Pris efter tilbud'}],params.get('pris'))}<p class="muted small">Prisfilteret bruger demopris ved minimumsantal, ekskl. tryk og moms.</p><button type="submit" class="button">Anvend filtre</button><a href="/produkter" class="text-link">Nulstil alle filtre</a></form></details><div><div class="results-bar"><span>${filtered.length} produkter${params.get('q')?` for “${esc(params.get('q'))}”`:''}</span><label class="sort-label">Sortér efter<select id="sort"><option value="">Udvalgte</option><option value="navn" ${params.get('sortering')==='navn'?'selected':''}>Navn A–Å</option><option value="pris-stigende" ${params.get('sortering')==='pris-stigende'?'selected':''}>Pris: lav til høj</option><option value="pris-faldende" ${params.get('sortering')==='pris-faldende'?'selected':''}>Pris: høj til lav</option></select></label></div><div class="product-grid catalog-grid">${filtered.length?filtered.map(card).join(''):`<div class="empty"><h2>Ingen produkter matcher.</h2><p>Prøv en anden søgning eller fjern et filter.</p><p><a class="text-link" href="/specialproduktion">Kan du ikke finde det, du søger? Beskriv dit ønske ↗</a></p><a class="button" href="/produkter">Se alle produkter</a></div>`}</div></div></section>`;}
function breakdown(p,line){const q=quoteLine(p,line);if(q.error)return `<p class="error">${q.error}</p>`;return `<dl class="price-breakdown"><div><dt>Produkt · ${q.quantity} stk.${q.unit!==null?` × ${money(q.unit)}`:''}</dt><dd>${money(q.goods)}</dd></div><div><dt>Tryk / dekoration</dt><dd>${money(q.print)}</dd></div><div><dt>Opstart</dt><dd>${money(q.setup)}</dd></div><div><dt>Fragt</dt><dd>Afklares i tilbud</dd></div><div class="total"><dt>Demoestimat, ekskl. moms og fragt</dt><dd>${money(q.subtotal)}</dd></div></dl>`;}
function productPage(id){const p=catalog.products.find(p=>p.id===id);if(!p)return `<div class="wrap empty"><h1>Produktet findes ikke.</h1><a href="/produkter">Tilbage til produkterne</a></div>`;activeProduct=p;draft={productId:p.id,color:p.colors[0].name,quantities:Object.fromEntries(p.sizes.map((s,i)=>[s,i===0?p.minimum:0])),method:p.prints[0].id,position:p.prints[0].positions[0],options:Object.fromEntries(Object.entries(p.options||{}).map(([n,v])=>[n,v[0]])),notes:'',logo:null};return `<div class="wrap breadcrumbs"><a href="/produkter">Produkter</a><span>/</span><a href="/produkter?kategori=${p.category}">${catalog.categories.find(c=>c.id===p.category).name}</a><span>/</span>${p.name}</div><section class="wrap product-detail"><div><div class="gallery-main">${p.art?art(p):`<img id="main-image" src="${p.colors[0].images[0]}" alt="${p.name} — ${p.colors[0].name}" width="700" height="800">`}<span class="image-tag">DEMOPRODUKT</span></div><div id="thumbnails" class="thumbnails"></div><p class="small muted">Illustrationsbilleder. Endeligt produkt og specifikationer bekræftes i tilbuddet.</p><details class="specs"><summary>Materialer og produktinformation</summary><dl><dt>Materiale (demo)</dt><dd>${p.material}</dd><dt>Varenummer</dt><dd>${p.sku}</dd><dt>Lager / levering</dt><dd>Afklares i tilbud</dd><dt>Datakilde</dt><dd>Lokalt demokatalog · ikke leverandørtilsluttet</dd></dl></details></div><div class="product-config"><p class="eyebrow">${p.brand}</p><h1>${p.name}</h1><p class="description">${p.description}</p><div class="product-price">${p.tiers.length?`Fra ${money(p.tiers.at(-1).unit)}`:'Få tilbud'}</div><p class="small muted">${p.tiers.length?`Demopris ved ${p.tiers.at(-1).min} stk. · ekskl. moms og tryk`:'Endelig pris beregnes efter dine specifikationer.'}</p><form id="configure"><fieldset><legend>01. Vælg farve <span id="selected-color">${draft.color}</span></legend><div class="swatches">${p.colors.map((c,i)=>`<label title="${c.name}"><input type="radio" name="color" value="${c.name}" ${i===0?'checked':''}><span style="background:${c.hex}"></span><b>${c.name}</b></label>`).join('')}</div></fieldset><fieldset><legend>02. Vælg antal <span>Min. ${p.minimum} stk. (demo)</span></legend><div class="size-grid">${p.sizes.map((s,i)=>`<label>${s==='Standard'?'Antal':s}<input type="number" name="qty-${s}" aria-label="Antal ${s}" value="${i===0?p.minimum:0}" min="0" max="100000" step="1" required></label>`).join('')}</div>${p.tiers.length?`<div class="tiers">${p.tiers.map(t=>`<span>${t.min}+ stk.<strong>${money(t.unit)}</strong></span>`).join('')}</div><p class="small muted">Demopriser pr. stk. uden moms og tryk.</p>`:''}</fieldset><fieldset><legend>03. Tryk og detaljer</legend><div class="form-grid"><label>Trykmetode<select name="method">${p.prints.map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select></label><label>Placering<select name="position" id="position"></select></label>${Object.entries(p.options||{}).map(([name,values])=>`<label>${name}<select name="option-${name}">${values.map(v=>`<option>${v}</option>`).join('')}</select></label>`).join('')}</div><label class="upload">Tilføj logo eller trykfil<input type="file" id="logo-upload" accept=".eps,.cdr,.pdf,.ai"><span>EPS, CDR, PDF eller AI · maks. 5 MB · gemmes kun i din browser</span></label><div id="logo-status" class="small" aria-live="polite"></div><label>Bemærkninger<textarea name="notes" rows="3" maxlength="2000" placeholder="Fortæl os om dit design eller særlige ønsker"></textarea></label></fieldset><div id="config-summary" aria-live="polite"></div><p id="config-error" class="error" role="alert"></p><button type="submit" class="button wide">Tilføj til tilbudskurv <span>↗</span></button><p class="small muted">Du bestiller ikke noget. Du samler dine ønsker til et tilbud.</p></form></div></section><section class="wrap section"><div class="section-heading"><h2>Mere til dit brand</h2><a href="/produkter">Alle produkter ↗</a></div><div class="product-grid">${catalog.products.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`;}
function lineDescription(p,l){return `${esc(l.color)} · ${esc(Object.entries(l.quantities).filter(([,n])=>n>0).map(([s,n])=>`${s}: ${n}`).join(', '))}<br>${esc(p.prints.find(m=>m.id===l.method)?.name||'Ukendt tryk')} · ${esc(l.position)}${Object.keys(l.options||{}).length?`<br>${esc(Object.entries(l.options).map(([k,v])=>`${k}: ${v}`).join(' · '))}`:''}${l.logo?`<br>Logo: ${esc(l.logo.name)} · gemt i denne browser`:''}${l.notes?`<br>Bemærkning: ${esc(l.notes)}`:''}`;}
function cartPage(){return `<section class="wrap section"><p class="eyebrow">DINE VALG, SAMLET ÉT STED</p><h1>Din tilbudskurv<span class="title-count">${cart.length}</span></h1>${!cart.length?`<div class="empty"><h2>Her er plads til dit næste projekt.</h2><p>Find et produkt, vælg detaljer, og føj det til din kurv.</p><a class="button" href="/produkter">Udforsk produkterne ↗</a></div>`:`<div class="cart-layout"><div>${cart.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);if(!p)return `<article class="cart-item">Produkt ikke længere tilgængeligt.<button data-remove="${esc(l.id)}">Fjern</button></article>`;return `<article class="cart-item"><a class="cart-image" href="/produkt/${p.id}">${picture({...p,colors:[p.colors.find(c=>c.name===l.color)||p.colors[0]]})}</a><div><a class="product-title" href="/produkt/${p.id}">${p.name}</a><p class="small line-details">${lineDescription(p,l)}</p><div class="cart-quantities">${p.sizes.map(s=>`<label>${s==='Standard'?'Antal':s}<input type="number" min="0" max="100000" step="1" value="${l.quantities[s]||0}" data-quantity="${esc(l.id)}" data-size="${s}" aria-label="${p.name} antal ${s}"></label>`).join('')}</div><p class="small muted">Mindst ${p.minimum} stk. i alt</p><p class="error" id="error-${esc(l.id)}"></p><div class="line-price" id="price-${esc(l.id)}">${breakdown(p,l)}</div><div class="line-actions">${l.logo?`<button type="button" class="text-link" data-download="${esc(l.logo.id)}" data-filename="${esc(l.logo.name)}">Hent vedhæftet logo</button>`:''}<button class="text-link" data-remove="${esc(l.id)}">Fjern produkt</button></div></div></article>`}).join('')}<a class="text-link" href="/produkter">← Find flere produkter</a></div><aside class="cart-summary"><h2>Din forespørgsel</h2><div id="cart-total"></div><p class="notice">Lokal demo. Intet bliver sendt, og du foretager ingen bestilling.</p><a class="button wide" href="/gennemgang">Gennemgå forespørgsel ↗</a><p class="small muted">Tilføj kontaktoplysninger på næste trin.</p></aside></div>`}</section>`;}
function cartTotals(){const qs=cart.map(l=>quoteLine(catalog.products.find(p=>p.id===l.productId),l));const invalid=qs.some(q=>q.error),unknown=qs.some(q=>q.subtotal===null),known=qs.reduce((s,q)=>s+(q.subtotal||0),0);return `<div class="total-row"><span>${cart.length} produkter</span><strong>${invalid?'Ret antal':unknown?'Få tilbud':money(known)}</strong></div>${unknown&&known?`<p class="small">Kendte demoestimater: ${money(known)}. Hertil kommer produkter uden pris.</p>`:''}<p class="small muted">Ekskl. moms og fragt. Alle beløb er demoestimater.</p>`;}
function reviewPage(){if(!cart.length)return cartPage();return `<section class="wrap section review"><p class="eyebrow">SIDSTE OVERBLIK</p><h1>Gennemgå din forespørgsel.</h1><p class="intro">Saml kontaktoplysninger og ønsker. I demoen kan du hente en lokal kopi — intet sendes.</p><div class="cart-layout"><form id="review-form"><h2>Dine oplysninger</h2><div class="form-grid">${[{name:'name',label:'Navn',required:true,auto:'name'},{name:'company',label:'Virksomhed / forening',required:true,auto:'organization'},{name:'email',label:'E-mail',type:'email',required:true,auto:'email'},{name:'phone',label:'Telefon',type:'tel',required:true,auto:'tel'},{name:'cvr',label:'CVR (valgfrit)',pattern:'[0-9]{8}'},{name:'date',label:'Ønsket leveringsdato (valgfrit)',type:'date'}].map(f=>`<label>${f.label}${f.required?' *':''}<input name="${f.name}" type="${f.type||'text'}" ${f.required?'required':''} ${f.auto?`autocomplete="${f.auto}"`:''} ${f.pattern?`pattern="${f.pattern}" title="CVR skal bestå af 8 cifre"`:''} ${f.type==='date'?`min="${new Date().toLocaleDateString('sv-SE')}"`:''} maxlength="200" value="${esc(contact[f.name]||'')}"></label>`).join('')}</div><label>Bemærkninger<textarea name="message" rows="4" maxlength="3000" placeholder="Fx event, deadline eller særlige ønsker">${esc(contact.message||'')}</textarea></label><p class="small muted">Kontaktoplysninger holdes kun i denne fane, medmindre du henter en kopi.</p><p class="error" id="review-error" role="alert"></p><button class="button" type="submit">Vis samlet forespørgsel ↗</button></form><aside class="cart-summary"><h2>Dine produkter</h2>${cart.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);return `<div class="review-line"><strong>${esc(p?.name||'Ukendt produkt')}</strong><p class="small">${totalQuantity(l)} stk. · ${esc(l.color)}</p></div>`}).join('')}${cartTotals()}<a href="/kurv" class="text-link">Ret din kurv</a></aside></div><div id="review-result" tabindex="-1"></div></section>`;}
function contactPage(){return `<section class="wrap section contact-page"><p class="eyebrow">LAD OS FINDE DET RIGTIGE MATCH</p><h1>Dit næste projekt<br>starter med en idé.</h1><p class="intro">Saml de produkter, du overvejer, og fortæl om antal, logo og ønsket levering i din tilbudskurv.</p><a class="button" href="/produkter">Find produkter ↗</a><div class="contact-notice"><h2>Kontaktoplysninger er på vej</h2><p>Telefon, e-mail og virksomhedsoplysninger er endnu ikke tilføjet til denne lokale prototype. Ingen henvendelser kan sendes fra siden endnu.</p></div></section>`;}
function designPage(id){
 const product=pfCatalog?.products.find(product=>product.id===id);
 if(!pfCatalog)return '<section class="wrap section"><div class="empty"><h1>Produktkataloget kan ikke indlæses lige nu.</h1><a href="/produkter">Tilbage til produkterne</a></div></section>';
 if(!product)return pfDesign(pfCatalog,id,pfPrices);
 if(isComingSoonProduct(product,pfPrices))return pfComingSoon(product);
 if(isQuoteOnlyProduct(product,pfPrices))return `<section class="wrap section"><div class="empty"><h1>${esc(product.name)}</h1><p>Prisen på dette produkt skal afklares, før vi kan lave et tilbud.</p><a class="button" href="/specialproduktion?produkt=${encodeURIComponent(product.id)}">Beskriv dit ønske →</a><p><a class="text-link" href="/produkter">Se flere produkter ↗</a></p></div></section>`;
 if(!isShopProduct(product,pfPrices))return `<section class="wrap section"><div class="empty"><h1>Produktet kan ikke vises i shoppen endnu.</h1><p>${esc(product.name)} mangler en sikker pris og bliver tilgængelig igen, når prisdata er på plads.</p><a class="button" href="/produkter">Se produkter med pris →</a><p><a class="text-link" href="/specialproduktion?produkt=${encodeURIComponent(product.id)}">Spørg os om produktet ↗</a></p></div></section>`;
 if(product.detail!==false)return pfDesign(pfCatalog,id,pfPrices);
 if(!pfProductRequests.has(id))pfProductRequests.set(id,fetch(`/api/pf-product/${encodeURIComponent(id)}`).then(response=>{if(!response.ok)throw Error('Produktet kunne ikke indlæses.');return response.json();}).then(detail=>{const index=pfCatalog.products.findIndex(product=>product.id===id);if(index>=0)pfCatalog.products[index]=detail;if(location.pathname===`/design/${id}`)render();}).catch(error=>{pfProductRequests.delete(id);if(location.pathname===`/design/${id}`){$('#main').innerHTML=`<div class="wrap empty"><h1>${esc(error.message)}</h1><button class="button" id="retry-product">Prøv igen</button></div>`;$('#retry-product')?.addEventListener('click',()=>render());}}));
 return '<section class="wrap section"><p class="eyebrow">DESIGNVÆRKTØJ</p><h1>Indlæser produktets muligheder…</h1></section>';
}
function render(){if(!catalog)return;closeProductMenu();if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}activeProduct=null;const path=location.pathname;$('#main').innerHTML=path==='/'?home():path==='/specialproduktion'?specialPage(pfCatalog?.products.find(p=>p.id===new URLSearchParams(location.search).get('produkt'))):path==='/brands'?brandsPage(visibleBrands(),location.search):path==='/produkter'?listing():path.startsWith('/design/')?designPage(path.split('/')[2]):path.startsWith('/produkt/')?productPage(path.split('/')[2]):path==='/kurv'?pfCartPage(pfCatalog,cart.length):path==='/betaling'?checkoutPage():path==='/ordre'?orderPage():path==='/demokurv'?cartPage():path==='/gennemgang'?reviewPage():path==='/kontakt'?contactPage():`<div class="wrap empty"><h1>Siden findes ikke</h1><a href="/produkter">Se produkterne</a></div>`;document.title=path==='/'?'Smerch':`${(path.startsWith('/design/')?pfCatalog?.products.find(p=>p.id===path.split('/')[2])?.name:null)||activeProduct?.name||({'/produkter':'Produkter','/brands':'Udvalgte brands','/specialproduktion':'Specialproduktion','/kurv':'Din kurv','/betaling':'Betaling','/ordre':'Din ordre','/demokurv':'Demo-tilbudskurv','/gennemgang':'Gennemgå forespørgsel','/kontakt':'Kontakt'}[path]||'Side ikke fundet')} | Smerch`;$('#search-input').value=new URLSearchParams(location.search).get('q')||'';updateCartHeader();$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('#navigation a').forEach(a=>a.removeAttribute('aria-current'));const selected=[...document.querySelectorAll('#navigation a')].find(a=>a.getAttribute('href')===location.pathname+location.search);selected?.setAttribute('aria-current','page');bind();}
function setGallery(){const images=activeProduct.colors.find(c=>c.name===draft.color).images;if(!images.length)return;$('#main-image').src=images[0];$('#main-image').alt=`${activeProduct.name} — ${draft.color}`;$('#thumbnails').innerHTML=images.map((src,i)=>`<button type="button" data-gallery="${src}" aria-label="Vis ${i===0?'forside':'bagside'}" aria-pressed="${i===0}"><img src="${src}" alt="${i===0?'Forside':'Bagside'}" width="80" height="90"></button>`).join('');}
function readDraft(){const form=$('#configure');for(const s of activeProduct.sizes)draft.quantities[s]=Number(form.elements[`qty-${s}`].value);draft.color=form.elements.color.value;draft.method=form.elements.method.value;draft.position=form.elements.position.value;draft.notes=form.elements.notes.value;for(const name of Object.keys(activeProduct.options||{}))draft.options[name]=form.elements[`option-${name}`].value;}
function updateConfig(){readDraft();$('#config-summary').innerHTML=breakdown(activeProduct,draft);$('#selected-color').textContent=draft.color;}
const customerCopy=value=>String(value).replaceAll('PF CONCEPT · ','SMERCH · ').replaceAll('PF Concept-produkter · ','').replaceAll('PF Concepts','leverandørens').replaceAll('PF Concept','leverandøren').replaceAll('PF’s','leverandørens').replace('Produkter og trykvalg fra leverandøren ·','Produkter og trykvalg ·').replace('Produkterne er hentet fra leverandøren.','Produkterne er udvalgt til vores sortiment.').replaceAll('leverandørens trykmuligheder','trykmuligheder').replaceAll('leverandørens placeringsbillede','Placeringsbillede').replaceAll('Placeringen ses på leverandørens billede ovenfor.','Placeringen ses på billedet ovenfor.').replaceAll('leverandøren:','Trykplacering:').replaceAll('leverandørens trykmål og korrektur styrer produktionen.','De angivne trykmål og den endelige korrektur styrer produktionen.').replace(/(\d+) produkter fra (\d+) brands\./,'$1 produkter i vores udvalg · $2 brands.');
function scrubCustomerCopy(root=document){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const clean=customerCopy(node.nodeValue);if(clean!==node.nodeValue)node.nodeValue=clean;}
 const elements=root.nodeType===Node.ELEMENT_NODE?[root,...root.querySelectorAll('*')]:[...root.querySelectorAll?.('*')||[]];
 elements.forEach(element=>{for(const name of ['alt','title','aria-label'])if(element.hasAttribute(name))element.setAttribute(name,customerCopy(element.getAttribute(name)));});
 elements.filter(element=>element.matches('a')).forEach(link=>{if(link.textContent.includes('Se leverandørens oplysninger'))link.remove();else if(link.href.includes('pfconcept.com')&&link.querySelector('img'))link.replaceWith(...link.childNodes);});
}
let supplierCopyObserver;
function bind(){
 scrubCustomerCopy(document);
 if(!supplierCopyObserver){supplierCopyObserver=new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE){const clean=customerCopy(node.nodeValue);if(clean!==node.nodeValue)node.nodeValue=clean;}else if(node.nodeType===Node.ELEMENT_NODE)scrubCustomerCopy(node);})));supplierCopyObserver.observe(document.body,{childList:true,subtree:true});}
 if(pfCatalog){bindPF(pfCatalog,nav,notify,pfPrices);bindCart(pfCatalog,nav,notify);}
 bindCheckout(notify);
 bindSpecial();
 $('#filters')?.addEventListener('submit',e=>{e.preventDefault();const params=new URLSearchParams(new FormData(e.currentTarget));for(const [k,v] of [...params])if(!v)params.delete(k);const sort=$('#sort').value;if(sort)params.set('sortering',sort);nav('/produkter'+(params.size?'?'+params:''));});
 $('#sort')?.addEventListener('change',e=>{const params=new URLSearchParams(location.search);if(e.target.value)params.set('sortering',e.target.value);else params.delete('sortering');nav('/produkter'+(params.size?'?'+params:''));});
 if(activeProduct){const form=$('#configure');const positions=()=>{$('#position').innerHTML=activeProduct.prints.find(m=>m.id===form.elements.method.value).positions.map(p=>`<option>${p}</option>`).join('');};positions();setGallery();updateConfig();
 form.addEventListener('input',e=>{if(e.target.type!=='file')updateConfig();});form.addEventListener('change',e=>{if(e.target.name==='method')positions();if(e.target.name==='color'){readDraft();setGallery();}if(e.target.type!=='file')updateConfig();});
 $('#logo-upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const capturedDraft=draft;$('#config-error').textContent='';form.querySelector('[type=submit]').disabled=true;try{const saved=await saveFile(file);if(capturedDraft!==draft||!document.contains(form)){await deleteFile(saved.id);return;}if(draft.logo)await deleteFile(draft.logo.id);draft.logo=saved;$('#logo-status').textContent=`${file.name} er gemt lokalt. Ingen fil er sendt.`;}catch(error){$('#config-error').textContent=error.message;e.target.value='';}finally{form.querySelector('[type=submit]').disabled=false;}});
 form.addEventListener('submit',e=>{e.preventDefault();readDraft();const error=validateLine(activeProduct,draft);if(error){$('#config-error').textContent=error;return;}cart.push({...structuredClone(draft),id:crypto.randomUUID()});if(!persist()){cart.pop();return;}nav('/demokurv');notify('Demoproduktet er tilføjet til din tilbudskurv.');});
 }
 if($('#cart-total'))$('#cart-total').innerHTML=cartTotals();
 document.querySelectorAll('[data-quantity]').forEach(input=>input.addEventListener('change',()=>{const line=cart.find(l=>l.id===input.dataset.quantity),p=catalog.products.find(p=>p.id===line.productId);const updated={...line,quantities:{...line.quantities,[input.dataset.size]:Number(input.value)}};const error=validateLine(p,updated);const errorEl=document.getElementById(`error-${line.id}`);if(error){errorEl.textContent=error;input.value=line.quantities[input.dataset.size]||0;return;}errorEl.textContent='';line.quantities=updated.quantities;persist();input.closest('.cart-item').querySelector('.line-details').innerHTML=lineDescription(p,line);document.getElementById(`price-${line.id}`).innerHTML=breakdown(p,line);$('#cart-total').innerHTML=cartTotals();}));
 $('#review-form')?.addEventListener('submit',e=>{e.preventDefault();const error=cart.map(l=>validateLine(catalog.products.find(p=>p.id===l.productId),l)).find(Boolean);if(error){$('#review-error').textContent=error;return;}contact=Object.fromEntries(new FormData(e.currentTarget));$('#review-result').innerHTML=`<div class="review-complete"><p class="eyebrow">KLAR TIL GENNEMGANG · IKKE SENDT</p><h2>Her er din samlede forespørgsel.</h2><p>${esc(contact.name)} · ${esc(contact.company)}<br>${esc(contact.email)} · ${esc(contact.phone)}${contact.cvr?`<br>CVR: ${esc(contact.cvr)}`:''}${contact.date?`<br>Ønsket levering: ${esc(contact.date)}`:''}</p>${contact.message?`<p>${esc(contact.message)}</p>`:''}${cart.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);return `<div class="review-line"><h3>${p.name}</h3><p>${lineDescription(p,l)}</p>${breakdown(p,l)}</div>`}).join('')}<p class="notice">Dette er kun en lokal gennemgang. Ingen forespørgsel er sendt. Kontaktoplysninger og logoer overføres ikke til en leverandør.</p><button type="button" class="button" id="download-quote">Hent forespørgsel som tekst</button><p class="small muted">Tekstfilen indeholder dine kontaktoplysninger og filnavne. Logoerne er separate filer i kurven.</p></div>`;$('#review-result').focus();$('#review-result').scrollIntoView({behavior:'smooth',block:'start'});$('#download-quote').addEventListener('click',()=>{const text=['SMERCH — LOKAL DEMO / IKKE SENDT','Alle priser er demoestimater, ekskl. moms og fragt.',...Object.entries(contact).map(([k,v])=>`${k}: ${v}`),'',...cart.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);return `${p.name} (${p.sku})\n${l.color} / ${JSON.stringify(l.quantities)}\n${p.prints.find(m=>m.id===l.method).name} / ${l.position}\n${JSON.stringify(l.options)}\nBemærkninger: ${l.notes}\nLogo: ${l.logo?.name||'Ikke vedhæftet'}\nDemoestimat: ${money(quoteLine(p,l).subtotal)}`;})].join('\n\n');downloadBlob(new Blob([text],{type:'text/plain;charset=utf-8'}),'smerch-forespoergsel-demo.txt');});});
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#product-menu-toggle').addEventListener('click',()=>$('#product-menu').hidden?openProductMenu(new URLSearchParams(location.search).get('kategori')):closeProductMenu());
$('#product-menu').addEventListener('click',event=>{const group=event.target.closest('[data-menu-group]');if(group){event.stopPropagation();openProductMenu(group.dataset.menuGroup);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#product-menu').hidden){closeProductMenu();$('#product-menu-toggle').focus();}});
document.addEventListener('click',event=>{if(!$('#product-menu').hidden&&!event.target.closest('#product-menu, #product-menu-toggle'))closeProductMenu();});
document.addEventListener('click',async e=>{const link=e.target.closest('a');if(link&&link.origin===location.origin&&!link.hash&&!link.download&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();nav(link.pathname+link.search,{scrollTop:Boolean(link.closest('.pf-pagination'))});return;}const remove=e.target.closest('[data-remove]');if(remove){const item=cart.find(l=>l.id===remove.dataset.remove);const previous=cart;cart=cart.filter(l=>l.id!==remove.dataset.remove);if(!persist()){cart=previous;return;}if(item?.logo)deleteFile(item.logo.id).catch(()=>{});render();notify('Produktet er fjernet.');}const gallery=e.target.closest('[data-gallery]');if(gallery){$('#main-image').src=gallery.dataset.gallery;$('#main-image').alt=`${activeProduct.name} — ${gallery.getAttribute('aria-label')}`;document.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',b===gallery));}const dl=e.target.closest('[data-download]');if(dl){try{const file=await loadFile(dl.dataset.download);if(!file)throw Error();downloadBlob(file,dl.dataset.filename);}catch{notify('Filen findes ikke længere i browseren. Tilføj produktet igen med logoet.');}}});
$('#search').addEventListener('submit',e=>{e.preventDefault();const q=$('#search-input').value.trim();nav('/produkter'+(q?'?q='+encodeURIComponent(q):''));});
$('.menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);});
window.addEventListener('popstate',render);
window.addEventListener('pf-cart-change',updateCartHeader);
window.addEventListener('storage',()=>{updateCartHeader();if(location.pathname==='/kurv')render();});
pfCatalog=await fetch('/api/pf-catalog').then(r=>{if(!r.ok)throw Error('PF-katalog mangler');return r.json();}).catch(()=>null);
pfPrices=await fetch('/api/pf-product-prices').then(r=>{if(!r.ok)throw Error('PF-priser mangler');return r.json();}).catch(()=>({available:false,products:{},skus:{},message:'Priserne kan ikke vises lige nu.'}));
setInterval(async()=>{try{const response=await fetch('/api/pf-product-prices');if(!response.ok)return;const next=await response.json();if(!next.available)return;const previous=pfPrices;const changed=!previous?.available||previous.productDate!==next.productDate||JSON.stringify(previous.comingSoonIds)!==JSON.stringify(next.comingSoonIds);pfPrices=next;if(changed&&(location.pathname==='/produkter'||location.pathname==='/brands'||location.pathname==='/'||(location.pathname.startsWith('/design/')&&!document.querySelector('.pf-studio'))))render();}catch{}},5*60_000);
try{const response=await fetch('/api/catalog');if(!response.ok)throw Error();catalog=await response.json();const restored=cart.filter(l=>l.quantities&&typeof l.quantities==='object'&&!validateLine(catalog.products.find(p=>p.id===l.productId),l));if(restored.length!==cart.length){cart=restored;persist();notify('Ugyldige eller udgåede demoprodukter er fjernet fra kurven.');}render();}catch{$('#main').innerHTML='<div class="wrap empty"><h1>Kataloget kunne ikke indlæses.</h1><p>Kontrollér, at den lokale server kører, og genindlæs siden.</p><button onclick="location.reload()" class="button">Prøv igen</button></div>';}
